// Package sites holds the embedded regional P25 trunked site table and the
// geometry used to pick and tune a site: great-circle distance, nearest-site
// selection with hysteresis, and the wide-tuner center-frequency fit.
//
// The table covers the trunked sites of UT, ID, WY, CO, AZ, NV and NM. It
// is generated by ./sitegen from testfixtures/scanner/sites/*.csv (see
// generate.go) and embedded gzip-compressed; Table decodes it once on first
// use.
//
// Site latitude and longitude are estimates derived from the town or peak
// in the site name and are good to roughly 15 km. They are fine for picking
// the nearest site but must not be used for anything that needs a surveyed
// location.
package sites

import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed" // embeds the generated site table
	"errors"
	"fmt"
	"hash/fnv"
	"io"
	"strconv"
	"strings"
)

// Format is the first line of a generated table; Parse rejects any other.
const Format = "openmanetd-sites v1"

// Encryption summarizes encrypted traffic on a site.
type Encryption uint8

// Encryption values.
const (
	EncryptionUnknown Encryption = iota
	EncryptionNone
	EncryptionPartial
	EncryptionFull
)

// Band is a site's frequency band.
type Band uint8

// Band values.
const (
	BandUnknown Band = iota
	BandVHF
	Band700
	Band800
	BandMixed
)

// Phase is the P25 voice air interface.
type Phase uint8

// Phase values.
const (
	PhaseUnknown Phase = iota
	Phase1
	Phase2
)

// Site is one trunked site.
type Site struct {
	// Key is State + "-" + 8 hex digits of FNV-1a over state|system|name.
	Key         string
	State       string
	System      string
	Name        string
	County      string
	PhaseDetail string
	// ControlHz are the frequencies marked "control" in the source, in
	// source order. ASSUMPTION: the source does not say which is the
	// primary control channel and which are alternates; the first listed
	// is treated as preferred and the decoder hunts across all of them.
	ControlHz []uint64
	// VoiceHz are the frequencies marked "voice/traffic", in source order.
	VoiceHz []uint64
	// Lat and Lon are ~15 km estimates (see package doc).
	Lat       float64
	Lon       float64
	LowHz     uint64
	HighHz    uint64
	RTLNeeded uint8
	// WideNeeded is the source's count of 8 MHz wide tuners needed.
	WideNeeded uint8
	Band       Band
	Phase      Phase
	Encryption Encryption
}

// SpanHz is HighHz - LowHz.
func (s *Site) SpanHz() uint64 { return s.HighHz - s.LowHz }

// Frequencies returns control then voice frequencies in a new slice.
func (s *Site) Frequencies() []uint64 {
	out := make([]uint64, 0, len(s.ControlHz)+len(s.VoiceHz))
	out = append(out, s.ControlHz...)

	return append(out, s.VoiceHz...)
}

// Key derives the stable site key.
func Key(state, system, name string) string {
	h := fnv.New32a()
	_, _ = h.Write([]byte(state + "|" + system + "|" + name)) // hash writes never fail

	return state + "-" + fmt.Sprintf("%08x", h.Sum32())
}

//go:embed sites.dat.gz
var embedded []byte

// Table decodes the embedded site table. Each call decodes afresh, so
// long-lived callers (the scanner manager) cache the result.
func Table() ([]Site, error) {
	zr, err := gzip.NewReader(bytes.NewReader(embedded))
	if err != nil {
		return nil, fmt.Errorf("open embedded site table: %w", err)
	}
	defer zr.Close()

	return Parse(zr)
}

// ErrFormat reports a malformed site table.
var ErrFormat = errors.New("malformed site table")

// Parse decodes an uncompressed generated table:
//
//	openmanetd-sites v1
//	Y<TAB>system name                     (system dictionary, index order)
//	P<TAB>phase detail                    (phase dictionary, index order)
//	T<TAB>state<TAB>sys<TAB>name<TAB>county<TAB>lat<TAB>lon<TAB>band<TAB>phase
//	 <TAB>phaseDetail<TAB>enc<TAB>rtl<TAB>wide<TAB>ctrlHz,...<TAB>voiceHz,...
//
// Frequencies are decimal Hz. band, phase and enc are the numeric values of
// Band, Phase and Encryption; sys and phaseDetail index the dictionaries.
func Parse(r io.Reader) ([]Site, error) {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 0, 4096), 64*1024)

	if !sc.Scan() || sc.Text() != Format {
		return nil, fmt.Errorf("%w: missing %q header", ErrFormat, Format)
	}

	var (
		systems []string
		details []string
		out     = make([]Site, 0, 300)
		line    = 1
	)

	for sc.Scan() {
		line++

		text := sc.Text()
		if text == "" {
			continue
		}

		kind, rest, _ := strings.Cut(text, "\t")

		switch kind {
		case "Y":
			systems = append(systems, rest)
		case "P":
			details = append(details, rest)
		case "T":
			s, err := parseSite(rest, systems, details)
			if err != nil {
				return nil, fmt.Errorf("%w: line %d: %w", ErrFormat, line, err)
			}

			out = append(out, s)
		default:
			return nil, fmt.Errorf("%w: line %d: unknown record %q", ErrFormat, line, kind)
		}
	}

	if err := sc.Err(); err != nil {
		return nil, fmt.Errorf("read site table: %w", err)
	}

	return out, nil
}

const siteFields = 14

func parseSite(rest string, systems, details []string) (Site, error) {
	f := strings.Split(rest, "\t")
	if len(f) != siteFields {
		return Site{}, fmt.Errorf("want %d fields, got %d", siteFields, len(f))
	}

	var (
		s    = Site{State: f[0], Name: f[2], County: f[3]}
		errs []error
	)

	idx := func(v string, dict []string) string {
		i, err := strconv.Atoi(v)
		if err != nil || i < 0 || i >= len(dict) {
			errs = append(errs, fmt.Errorf("bad dictionary index %q", v))

			return ""
		}

		return dict[i]
	}
	small := func(v string) uint8 {
		n, err := strconv.ParseUint(v, 10, 8)
		if err != nil {
			errs = append(errs, fmt.Errorf("bad number %q: %w", v, err))
		}

		return uint8(n)
	}
	float := func(v string) float64 {
		n, err := strconv.ParseFloat(v, 64)
		if err != nil {
			errs = append(errs, fmt.Errorf("bad coordinate %q: %w", v, err))
		}

		return n
	}

	s.System = idx(f[1], systems)
	s.Lat = float(f[4])
	s.Lon = float(f[5])
	s.Band = Band(small(f[6]))
	s.Phase = Phase(small(f[7]))
	s.PhaseDetail = idx(f[8], details)
	s.Encryption = Encryption(small(f[9]))
	s.RTLNeeded = small(f[10])
	s.WideNeeded = small(f[11])

	var err error
	if s.ControlHz, err = parseFreqs(f[12]); err != nil {
		errs = append(errs, err)
	}

	if s.VoiceHz, err = parseFreqs(f[13]); err != nil {
		errs = append(errs, err)
	}

	if len(s.ControlHz) == 0 {
		errs = append(errs, errors.New("site has no control channel"))
	}

	if err = errors.Join(errs...); err != nil {
		return Site{}, err
	}

	s.Key = Key(s.State, s.System, s.Name)
	s.LowHz, s.HighHz = bounds(s.ControlHz, s.VoiceHz)

	return s, nil
}

func parseFreqs(v string) ([]uint64, error) {
	if v == "" {
		return nil, nil
	}

	out := make([]uint64, 0, strings.Count(v, ",")+1)

	for p := range strings.SplitSeq(v, ",") {
		n, err := strconv.ParseUint(p, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("bad frequency %q: %w", p, err)
		}

		out = append(out, n)
	}

	return out, nil
}

func bounds(lists ...[]uint64) (lo, hi uint64) {
	for _, l := range lists {
		for _, f := range l {
			if lo == 0 || f < lo {
				lo = f
			}

			if f > hi {
				hi = f
			}
		}
	}

	return lo, hi
}

// ByKey returns the site with key, or false.
func ByKey(all []Site, key string) (*Site, bool) {
	for i := range all {
		if all[i].Key == key {
			return &all[i], true
		}
	}

	return nil, false
}
